select* from customer_behaviour limit 10;


**Q1.** what is the total revenue generated by male vs female customers.
SELECT gender, SUM("Purchase_Amount") AS revenue
FROM customer_behaviour
GROUP BY gender;



**Q2.** which customer used a discount but still spent more than the average purchase amount?
select "Purchase_Amount",customer_id from customer_behaviour
where discount_applied='Yes' and 
"Purchase_Amount">=(select avg("Purchase_Amount")from customer_behaviour);


**Q3.** Which are the top 5 products with the highest average review rating?
SELECT item_purchased,
ROUND(AVG(review_rating)::numeric, 2) AS avg_review_rating
from customer_behaviour
group by item_purchased
order by avg_review_rating DESC
limit 5;



**Q4.** Compare the average Purchase Amounts between Standard and Express Shipping.
select shipping_type,
       round(avg("Purchase_Amount")::numeric, 2) as avg_purchase_amount
from customer_behaviour
where shipping_type in ('Standard', 'Express')
group by shipping_type;



**Q5.** Do subscribed customers spend more? Compare average spend and 
total revenue between subscribers and non-subscribers.
select subscription_status,
       round(avg("Purchase_Amount")::numeric, 2) as avg_spend,
       sum("Purchase_Amount") as total_revenue
from customer_behaviour
group by subscription_status;



**Q6.** Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased,
       round(
           count(*) filter (where discount_applied = 'Yes') * 100.0 / count(*),
           2
       ) as discount_percentage
from customer_behaviour
group by item_purchased
order by discount_percentage desc
limit 5;



**Q7.** Segment customers into New, Returning, and Loyal based 
on their total number of previous purchases, and show the count of each segment.
with customer_segments as (
    select customer_id,
           case
               when previous_purchases <= 1 then 'New'
               when previous_purchases between 2 and 5 then 'Returning'
               else 'Loyal'
           end as customer_segment
    from customer_behaviour
)
select customer_segment,
       count(distinct customer_id) as customer_count
from customer_segments
group by customer_segment
order by customer_count desc;


**Q8.** What are the top 3 most purchased products within each category?
with product_counts as (
    select
        category,
        item_purchased,
        count(*) as purchase_count,
        rank() over (
            partition by category
            order by count(*) desc
        ) as product_rank
    from customer_behaviour
    group by category, item_purchased
)
select
    category,
    item_purchased,
    purchase_count
from product_counts
where product_rank <= 3
order by category, product_rank;



**Q9.** Are customers who are repeat buyers (more than 5 previous purchases)
also likely to subscribe?
select subscription_status,
count(customer_id) as repeat_buyers
from customer_behaviour
where previous_purchases>5
group by subscription_status;



**Q10.** What is the revenue contribution of each age group?
select age_group,sum("Purchase_Amount") as total_revenue
from customer_behaviour group by age_group
order by total_revenue DESC;


